340→// NewFactoryAIDroidRunner creates a new Factory AI Droid runner with the given config.
341→func NewFactoryAIDroidRunner(config AgentRunnerConfig) *FactoryAIDroidRunner {
342→	model := config.Model
343→	if model == "" {
344→		model = os.Getenv("E2E_DROID_MODEL")
345→		// No default model — use droid's built-in default if not specified
346→	}
347→
348→	timeout := config.Timeout
349→	if timeout == 0 {
350→		if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
351→			if parsed, err := time.ParseDuration(envTimeout); err == nil {
352→				timeout = parsed
353→			}
354→		}
355→		if timeout == 0 {
356→			timeout = 2 * time.Minute
357→		}
358→	}
359→
360→	return &FactoryAIDroidRunner{
361→		Model:     model,
362→		Timeout:   timeout,
363→		AutoLevel: "medium",
364→	}
365→}
